        super.renderRecursively(pose,mob,bone,type,buffers,sink,rerender,partial,vein||mob.kind()==TemplateMob.Kind.CENTIPEDE&&bone.getName().startsWith("eye_")&&mob.skillId()==com.dynasty.blueprint.ArmySkills.CENTIPEDE_GAZE||mob.kind()==TemplateMob.Kind.BLIND_FISH&&(bone.getName().startsWith("dorsal_")||bone.getName().startsWith("ribbon_"))||mob.kind()==TemplateMob.Kind.LANTERN_BAT&&bone.getName().equals("flame")||mob.kind()==TemplateMob.Kind.TREE&&bone.getName().startsWith("fungus_")||mob.kind()==TemplateMob.Kind.TOAD&&(bone.getName().startsWith("venom_gland_")||bone.getName().startsWith("eye_"))||mob.kind()==TemplateMob.Kind.CHILD&&bone.getName().equals("lantern_flame")?15728880:light,overlay,
            vein?.75F:red,vein?.25F:green,vein?1F:blue,alpha);
